package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class PlayerAnalyticsService { private final PlayerRepository players; private final PlayerAttributeSnapshotRepository snapshots; private final PlayerProgressionRepository progressions; private final MatchRepository matches; public PlayerAnalyticsService(PlayerRepository players, PlayerAttributeSnapshotRepository snapshots, PlayerProgressionRepository progressions, MatchRepository matches){this.players=players;this.snapshots=snapshots;this.progressions=progressions;this.matches=matches;} @Transactional public PlayerAttributeSnapshot buildSnapshot(Long playerId, Long matchId){PlayerAttributeSnapshot s=new PlayerAttributeSnapshot(); s.setPlayer(players.findById(playerId).orElseThrow()); if(matchId!=null)matches.findById(matchId).ifPresent(s::setMatch); return snapshots.save(s);} public List<PlayerProgression> calculateProgression(Long playerId){return progressions.findByPlayer_IdOrderByRecordedAtDesc(playerId);} public String comparePlayers(Long playerA, Long playerB){Player a=players.findById(playerA).orElseThrow(); Player b=players.findById(playerB).orElseThrow(); return (a.getUser()!=null?a.getUser().getNom():"Player "+a.getId())+" vs "+(b.getUser()!=null?b.getUser().getNom():"Player "+b.getId());} }
